from itertools import permutations

# Define the people, colors, pets, and drinks
people = ['Casey', 'Devon', 'Parker', 'Sawyer']
colors = ['blue', 'green', 'orange', 'yellow']
pets = ['bird', 'cat', 'fish', 'rabbit']
drinks = ['cocoa', 'coffee', 'milk', 'tea']

# Brute force: check all possible assignments
solutions = []

for people_perm in permutations(people):
    for colors_perm in permutations(colors):
        for pets_perm in permutations(pets):
            for drinks_perm in permutations(drinks):
                # Create houses (0-indexed)
                houses = [
                    {'person': people_perm[i], 'color': colors_perm[i], 'pet': pets_perm[i], 'drink': drinks_perm[i]}
                    for i in range(4)
                ]

                # Helper functions to find positions
                def find_person(name):
                    for i, h in enumerate(houses):
                        if h['person'] == name:
                            return i
                    return -1

                def find_pet(pet_name):
                    for i, h in enumerate(houses):
                        if h['pet'] == pet_name:
                            return i
                    return -1

                def find_color(color_name):
                    for i, h in enumerate(houses):
                        if h['color'] == color_name:
                            return i
                    return -1

                def find_drink(drink_name):
                    for i, h in enumerate(houses):
                        if h['drink'] == drink_name:
                            return i
                    return -1

                # Get positions
                fish_pos = find_pet('fish')
                parker_pos = find_person('Parker')
                coffee_pos = find_drink('coffee')
                devon_pos = find_person('Devon')
                green_pos = find_color('green')
                sawyer_pos = find_person('Sawyer')
                cocoa_pos = find_drink('cocoa')
                orange_pos = find_color('orange')
                rabbit_pos = find_pet('rabbit')
                bird_pos = find_pet('bird')
                milk_pos = find_drink('milk')
                blue_pos = find_color('blue')

                # Check all 10 clues
                valid = True

                # Clue 1: Fish owner lives next to Parker
                if abs(fish_pos - parker_pos) != 1:
                    valid = False

                # Clue 2: Parker lives next to coffee drinker
                elif abs(parker_pos - coffee_pos) != 1:
                    valid = False

                # Clue 3: Devon lives next to green house
                elif abs(devon_pos - green_pos) != 1:
                    valid = False

                # Clue 4: Sawyer is not milk drinker
                elif houses[sawyer_pos]['drink'] == 'milk':
                    valid = False

                # Clue 5: Cocoa drinker lives next to orange house
                elif abs(cocoa_pos - orange_pos) != 1:
                    valid = False

                # Clue 6: Rabbit owner immediately left of coffee drinker
                elif rabbit_pos + 1 != coffee_pos:
                    valid = False

                # Clue 7: Parker immediately left of cocoa drinker
                elif parker_pos + 1 != cocoa_pos:
                    valid = False

                # Clue 8: Orange house not milk drinker
                elif houses[orange_pos]['drink'] == 'milk':
                    valid = False

                # Clue 9: Milk drinker immediately left of bird owner
                elif milk_pos + 1 != bird_pos:
                    valid = False

                # Clue 10: Rabbit owner immediately left of blue house
                elif rabbit_pos + 1 != blue_pos:
                    valid = False

                if valid:
                    solutions.append(houses)

# Find the fish owner from the solution
if solutions:
    for house in solutions[0]:
        if house['pet'] == 'fish':
            print(f"ANSWER: {house['person']}")
            break
